templates.template:

.u-blurContent {
    filter: blur(8px);
    -webkit-filter: blur(8px);
    user-select: none;
    pointer-events: none;
    transition: filter 0.3s ease;
}

.u-blurOverlay {
    position: relative;
    z-index: 100;
    margin-top: -60px;
    text-align: center;
    padding: 40px 20px;
    background: linear-gradient(to bottom, transparent, @xf-contentBg);

    .blur-message {
        font-weight: @xf-fontWeightHeavy;
        margin-bottom: @xf-paddingMedium;
    }
}
